(function(){'use strict';window.KTP_TOP10_54_BANKS=Object.assign(window.KTP_TOP10_54_BANKS||{},{"7a_l17":{"lines":{"standard":[{"n":1,"level":"A","text":"Сумма двух чисел равна 46, одно число на 8 больше другого. Найдите оба числа.","answer":"19 и 27","solution":"Пусть меньшее число x. Тогда большее x+8. x+(x+8)=46; 2x=38; x=19. Второе число 27."},{"n":2,"level":"A","text":"Сумма двух чисел равна 58, их разность равна 14. Найдите числа.","answer":"22 и 36","solution":"Пусть меньшее x, тогда большее x+14. x+x+14=58; 2x=44; x=22; x+14=36."},{"n":3,"level":"A","text":"Сумма трёх последовательных целых чисел равна 72. Найдите эти числа.","answer":"23, 24 и 25","solution":"Пусть первое x. Тогда x+(x+1)+(x+2)=72; 3x+3=72; x=23."},{"n":4,"level":"A","text":"Периметр прямоугольника равен 38 см, длина на 5 см больше ширины. Найдите стороны.","answer":"7 см и 12 см","solution":"Пусть ширина x см, длина x+5. 2x+2(x+5)=38; 4x+10=38; x=7; длина 12."},{"n":5,"level":"A","text":"В равнобедренном треугольнике основание на 4 см короче боковой стороны. Периметр равен 32 см. Найдите стороны.","answer":"12 см, 12 см и 8 см","solution":"Пусть боковая сторона x см, основание x-4. 2x+(x-4)=32; 3x=36; x=12; основание 8."},{"n":6,"level":"A","text":"В пяти одинаковых коробках и отдельно лежат ещё 7 карандашей. Всего 52 карандаша. Сколько карандашей в одной коробке?","answer":"9 карандашей","solution":"Пусть в коробке x карандашей. 5x+7=52; 5x=45; x=9."},{"n":7,"level":"A","text":"После того как из кошелька потратили 18 рублей, в нём осталось ровно половина первоначальной суммы. Сколько рублей было сначала?","answer":"36 рублей","solution":"Пусть было x рублей. x-18=0,5x; 0,5x=18; x=36."},{"n":8,"level":"A","text":"Возраст мамы в 3 раза больше возраста дочери, вместе им 48 лет. Сколько лет каждой?","answer":"12 лет и 36 лет","solution":"Пусть дочери x лет, маме 3x. x+3x=48; 4x=48; x=12; маме 36."},{"n":9,"level":"A","text":"В первый день ученик прочитал на 8 страниц меньше, чем во второй. За два дня он прочитал 64 страницы. Сколько страниц прочитано в каждый день?","answer":"28 и 36 страниц","solution":"Пусть в первый день x страниц, во второй x+8. x+x+8=64; 2x=56; x=28."},{"n":10,"level":"A","text":"После повышения цены на 10% товар стал стоить 660 рублей. Найдите исходную цену.","answer":"600 рублей","solution":"Пусть исходная цена x. После повышения: 1,1x=660; x=600."},{"n":11,"level":"A","text":"После скидки 20% товар стал стоить 800 рублей. Какова была цена до скидки?","answer":"1000 рублей","solution":"После скидки остаётся 80% цены: 0,8x=800; x=1000."},{"n":12,"level":"A","text":"После увеличения выпуска продукции на 15% получили 230 изделий. Сколько изделий выпускали раньше?","answer":"200 изделий","solution":"Новый выпуск равен 1,15x. 1,15x=230; x=200."},{"n":13,"level":"A","text":"Автомобиль едет на 30 км/ч быстрее велосипедиста. За 2 часа автомобиль проходит тот же путь, что велосипедист за 5 часов. Найдите скорости.","answer":"20 км/ч и 50 км/ч","solution":"Пусть скорость велосипедиста x, автомобиля x+30. 5x=2(x+30); 3x=60; x=20; автомобиль 50."},{"n":14,"level":"A","text":"Теплоход идёт 4 часа по течению и проходит тот же путь, что за 5 часов против течения. Скорость течения 2 км/ч. Найдите собственную скорость теплохода.","answer":"18 км/ч","solution":"Пусть собственная скорость x. 4(x+2)=5(x-2); 4x+8=5x-10; x=18."},{"n":15,"level":"A","text":"Два путешественника движутся в противоположных направлениях. Скорость одного на 12 км/ч больше скорости другого. За 3 часа расстояние между ними стало 216 км. Найдите скорости.","answer":"30 км/ч и 42 км/ч","solution":"Пусть меньшая скорость x, большая x+12. 3x+3(x+12)=216; 6x+36=216; x=30."},{"n":16,"level":"A","text":"Автомобиль движется на 20 км/ч быстрее мотоциклиста. За 3 часа автомобиль проходит тот же путь, что мотоциклист за 5 часов. Найдите скорости. Текстовые задачи с помощью уравнений 7 класс · урок №17","answer":"30 км/ч и 50 км/ч","solution":"Пусть скорость мотоциклиста x, автомобиля x+20. 5x=3(x+20); 2x=60; x=30."},{"n":17,"level":"A","text":"После скидки 25% куртка стала стоить 900 рублей. Найдите цену до скидки.","answer":"1200 рублей","solution":"После скидки остаётся 75%: 0,75x=900; x=1200. Текстовые задачи с помощью уравнений 7 класс · урок №17"},{"n":18,"level":"A","text":"В четырёх одинаковых коробках и отдельно лежат 3 карандаша. Всего 38 карандашей. Может ли в каждой коробке лежать одинаковое целое число карандашей? Обоснуйте.","answer":"Нет","solution":"4x+3=38; 4x=35; x=8,75. Число карандашей в коробке должно быть целым, поэтому найденный корень по смыслу не подходит."},{"n":19,"level":"B","text":"В классе 30 учеников, девочек на 4 больше, чем мальчиков. Сколько мальчиков и девочек?","answer":"13 мальчиков и 17 девочек","solution":"Пусть мальчиков x, девочек x+4. x+x+4=30; 2x=26; x=13."},{"n":20,"level":"B","text":"Стороны треугольника равны x см, x+4 см и 2x-3 см. Периметр равен 45 см. Найдите стороны.","answer":"11 см, 15 см и 19 см","solution":"x+(x+4)+(2x-3)=45; 4x+1=45; x=11."},{"n":21,"level":"B","text":"На двух полках 76 книг, на первой на 12 книг больше. Сколько книг было на каждой полке? Сколько станет на каждой, если с первой переложить 6 книг на вторую?","answer":"44 и 32; затем по 38","solution":"Пусть на второй x, на первой x+12. 2x+12=76; x=32; на первой 44. После переноса: 38 и 38."},{"n":22,"level":"B","text":"Цену сначала повысили на 20%, затем новую цену снизили на 10%. После двух изменений товар стоит 972 рубля. Найдите первоначальную цену.","answer":"900 рублей","solution":"После первого изменения цена 1,2x, после второго 0,9·1,2x=1,08x. 1,08x=972; x=900."},{"n":23,"level":"B","text":"Теплоход 4 часа шёл против течения и прошёл на 18 км больше, чем за 3 часа по течению. Скорость течения 2 км/ч. Найдите собственную скорость.","answer":"32 км/ч","solution":"4(x-2)=3(x+2)+18; 4x-8=3x+24; x=32."},{"n":24,"level":"B","text":"Пешеход и велосипедист одновременно отправились в противоположных направлениях. Велосипедист движется на 4 км/ч быстрее. Через 3 часа расстояние между ними стало 42 км. Найдите скорости.","answer":"5 км/ч и 9 км/ч","solution":"Пусть скорость пешехода x, велосипедиста x+4. 3x+3(x+4)=42; 6x+12=42; x=5."},{"n":25,"level":"B","text":"Грузовик выехал на 1 час раньше автомобиля. Скорость автомобиля на 20 км/ч больше. Через 2 часа после выезда автомобиля он догнал грузовик. Найдите скорости.","answer":"40 км/ч и 60 км/ч","solution":"Пусть скорость грузовика x, автомобиля x+20. Грузовик был в пути 3 часа: 3x=2(x+20); x=40."},{"n":26,"level":"B","text":"Сейчас отец в 4 раза старше сына. Через 6 лет возраст отца будет в 3 раза больше возраста сына. Сколько лет им сейчас?","answer":"12 лет и 48 лет","solution":"Пусть сыну x, отцу 4x. Через 6 лет: 4x+6=3(x+6); x=12; отцу 48."},{"n":27,"level":"B","text":"Пятирублёвых монет на 4 больше, чем десятирублёвых. Общая сумма 140 рублей. Сколько монет каждого вида?","answer":"12 пятирублёвых и 8 десятирублёвых","solution":"Пусть десятирублёвых x, пятирублёвых x+4. 10x+5(x+4)=140; 15x=120; x=8."},{"n":28,"level":"B","text":"Один из смежных углов на 24° больше другого. Найдите углы.","answer":"78° и 102°","solution":"Пусть меньший угол x, больший x+24. x+x+24=180; 2x=156; x=78."},{"n":29,"level":"B","text":"Сумма трёх последовательных чётных чисел равна 90. Найдите числа.","answer":"28, 30 и 32","solution":"Пусть первое x, затем x+2 и x+4. 3x+6=90; x=28."},{"n":30,"level":"B","text":"40% некоторого числа, увеличенные на 7, дают 31. Найдите число.","answer":"60","solution":"0,4x+7=31; 0,4x=24; x=60."},{"n":31,"level":"B","text":"После скидки 15% цена стала 1020 рублей. Найдите цену до скидки. Текстовые задачи с помощью уравнений 7 класс · урок №17","answer":"1200 рублей","solution":"После скидки остаётся 85%: 0,85x=1020; x=1200."},{"n":32,"level":"B","text":"За 4 часа против течения теплоход проходит на 10 км больше, чем за 3 часа по течению. Скорость течения 2 км/ч. Найдите собственную скорость.","answer":"24 км/ч","solution":"4(x-2)=3(x+2)+10; 4x-8=3x+16; x=24."},{"n":33,"level":"B","text":"Два спортсмена проходят одну и ту же дистанцию. Первый идёт 5 часов, второй движется на 3 км/ч быстрее и тратит 4 часа. Найдите скорости.","answer":"12 км/ч и 15 км/ч","solution":"Пусть скорость первого x, второго x+3. 5x=4(x+3); x=12."},{"n":34,"level":"B","text":"Тариф связи: 150 рублей абонентская плата и 8 рублей за каждую минуту сверх пакета. Счёт составил 310 рублей. Сколько платных минут использовано?","answer":"20 минут","solution":"150+8x=310; 8x=160; x=20. Текстовые задачи с помощью уравнений 7 класс · урок №17"},{"n":35,"level":"B","text":"Со склада продали 35% товара, после чего осталось 520 кг. Сколько килограммов было первоначально?","answer":"800 кг","solution":"Осталось 65%: 0,65x=520; x=800."},{"n":36,"level":"B","text":"Для прямоугольника получили модель: ширина x см, длина x-5 см, периметр 6 см. Решите уравнение и решите, существует ли такой прямоугольник.","answer":"Такого прямоугольника нет","solution":"2x+2(x-5)=6; 4x-10=6; x=4. Тогда длина x-5=-1 см, что невозможно."},{"n":37,"level":"C","text":"Ученик решает задачу: «Одно число на 7 меньше другого, сумма 41» и пишет x+(x-7)=41, считая x меньшим числом. В чём ошибка? Найдите числа.","answer":"17 и 24","solution":"Если x — меньшее число, большее равно x+7. Правильная модель: x+(x+7)=41; 2x=34; x=17; второе 24."},{"n":38,"level":"C","text":"Ученик заменил фразу «цена увеличилась на 20%» выражением x+20. Объясните ошибку и запишите правильную модель.","answer":"1,2x","solution":"20% зависят от исходной цены: 20% от x равно 0,2x. Новая цена x+0,2x=1,2x."},{"n":39,"level":"C","text":"Автомобиль движется со скоростью 72 км/ч в течение 30 минут. Какую величину нужно привести к другим единицам перед использованием s=vt? Найдите путь.","answer":"30 минут = 0,5 часа; 36 км","solution":"В формуле скорость дана в км/ч, поэтому время переводим в часы: 0,5 ч. s=72·0,5=36 км."},{"n":40,"level":"C","text":"Сумма двух чисел 44, одно на 10 больше другого. Решите задачу двумя способами: обозначьте x сначала меньшее, затем большее число.","answer":"17 и 27","solution":"1) x+(x+10)=44 → x=17. 2) x+(x-10)=44 → x=27. Оба выбора дают одну пару чисел."},{"n":41,"level":"C","text":"Составьте жизненную задачу, которая решается уравнением 3x+8=47, и решите её.","answer":"x=13; пример: три одинаковых набора и 8 отдельных предметов","solution":"Например: в трёх одинаковых коробках и отдельно 8 карандашей, всего 47. 3x+8=47; x=13."},{"n":42,"level":"C","text":"В задаче о реке ученик записал скорости x+3 и x+3 для движения по течению и против течения. Исправьте модель и объясните знак.","answer":"x+3 и x-3","solution":"Течение помогает по течению и мешает против него. Поэтому при скорости течения 3: vпо=x+3, vпротив=x-3."},{"n":43,"level":"C","text":"В задаче о числе предметов получилось уравнение 4x+2=19. Решите его и оцените ответ по смыслу, если x — число предметов в одной коробке.","answer":"x=4,25; по смыслу не подходит","solution":"4x=17; x=4,25. Число предметов должно быть целым, поэтому задача в таком виде не имеет допустимого решения."},{"n":44,"level":"C","text":"Цену увеличили на 25%, затем уменьшили на 20%. Вернулась ли цена к исходной? Обоснуйте без выбора конкретной цены. Текстовые задачи с помощью уравнений 7 класс · урок №17","answer":"Да","solution":"После увеличения: 1,25x. После уменьшения: 0,8·1,25x=x."},{"n":45,"level":"C","text":"Велосипедист едет 12 км/ч и выехал на 1 час раньше автомобиля со скоростью 36 км/ч. Через сколько часов после выезда автомобиля произойдёт встреча?","answer":"0,5 часа","solution":"Пусть автомобиль едет t часов. Велосипедист едет t+1 часов. 12(t+1)=36t; 12=24t; t=0,5."},{"n":46,"level":"C","text":"Пешеход идёт 4 км/ч и вышел на 1,5 часа раньше велосипедиста со скоростью 10 км/ч. Через сколько часов велосипедист догонит пешехода?","answer":"1 час","solution":"4(t+1,5)=10t; 4t+6=10t; 6t=6; t=1."},{"n":47,"level":"C","text":"Периметр прямоугольника 54 см, длина на 3 см меньше удвоенной ширины. Найдите стороны.","answer":"10 см и 17 см","solution":"Пусть ширина x, длина 2x-3. x+(2x-3)=27; 3x=30; x=10; длина 17."},{"n":48,"level":"C","text":"Тариф A: 120 рублей и 5 рублей за минуту. Тариф B: 60 рублей и 8 рублей за минуту. При каком числе минут стоимость одинакова? Контроль — полное понимание и перенос","answer":"20 минут","solution":"120+5x=60+8x; 60=3x; x=20."},{"n":49,"level":"Контроль","text":"Два товара вместе стоят 1250 рублей, один на 150 рублей дороже другого. Найдите цены.","answer":"550 и 700 рублей","solution":"Пусть дешевле x, дороже x+150. 2x+150=1250; 2x=1100; x=550."},{"n":50,"level":"Контроль","text":"Периметр прямоугольника 72 см, длина в 2 раза больше ширины. Найдите стороны.","answer":"12 см и 24 см","solution":"Пусть ширина x, длина 2x. 2x+2·2x=72; 6x=72; x=12."},{"n":51,"level":"Контроль","text":"Теплоход проходит один и тот же путь за 5 часов по течению и за 7 часов против течения. Скорость течения 3 км/ч. Найдите собственную скорость.","answer":"18 км/ч","solution":"5(x+3)=7(x-3); 5x+15=7x-21; 36=2x; x=18. Текстовые задачи с помощью уравнений 7 класс · урок №17"},{"n":52,"level":"Контроль","text":"После повышения цены на 12% товар стал стоить 1568 рублей. Найдите исходную цену.","answer":"1400 рублей","solution":"1,12x=1568; x=1400."},{"n":53,"level":"Контроль","text":"Велосипедист едет 14 км/ч и выехал на 2 часа раньше второго велосипедиста, который движется 21 км/ч. Через сколько часов после старта второго он догонит первого?","answer":"4 часа","solution":"14(t+2)=21t; 14t+28=21t; 7t=28; t=4."},{"n":54,"level":"Контроль","text":"При распределении детей по 6 одинаковым командам и ещё 5 дежурных получилось уравнение 6x+5=50. Решите уравнение и оцените результат по смыслу.","answer":"x=7,5; условие не допускает такого ответа","solution":"6x=45; x=7,5. Число детей в команде должно быть целым, поэтому математический корень не является допустимым ответом задачи."}]}},"11a_l18":{"lines":{"standard":[{"n":1,"level":"A","text":"Найдите производную и определите характер изменения f (x) = 3x + 4.","answer":"Возрастает на R.","solution":"f ′ (x) = 3 > 0 на всей R."},{"n":2,"level":"A","text":"Найдите производную и определите характер изменения f (x) = −2x + 5.","answer":"Убывает на R.","solution":"f ′ (x) = −2 < 0 на всей R."},{"n":3,"level":"A","text":"Найдите производную и определите характер изменения f (x) = 5x − 7.","answer":"Возрастает на R.","solution":"f ′ (x) = 5 > 0 на всей R."},{"n":4,"level":"A","text":"Найдите производную и определите характер изменения f (x) = −4x + 1.","answer":"Убывает на R.","solution":"f ′ (x) = −4 < 0 на всей R."},{"n":5,"level":"A","text":"Найдите производную и определите характер изменения f (x) = 1x − 6.","answer":"Возрастает на R.","solution":"f ′ (x) = 1 > 0 на всей R."},{"n":6,"level":"A","text":"Найдите производную и определите характер изменения f (x) = 9.","answer":"Постоянная на R.","solution":"f ′ (x) = 0 при всех x; функция постоянна."},{"n":7,"level":"A","text":"Исследуйте монотонность функции f (x) = (x − 2)2 + 1.","answer":"Возрастает: (2; +∞); убывает: (−∞; 2).","solution":"f ′ (x) = 2(x − 2); производная меняет знак при x = 2. Следовательно, f возрастает на (2; +∞), убывает на (−∞; 2)."},{"n":8,"level":"A","text":"Исследуйте монотонность функции f (x) = (x + 3)2. ","answer":"Возрастает: (−3; +∞); убывает: (−∞; −3).","solution":"f ′ (x) = 2(x + 3); производная меняет знак при x = −3. Следовательно, f возрастает на (−3; +∞), убывает на (−∞; −3)."},{"n":9,"level":"A","text":"Исследуйте монотонность функции f (x) = −(x − 1)2 + 2.","answer":"Возрастает: (−∞; 1); убывает: (1; +∞).","solution":"f ′ (x) = −2(x − 1); производная меняет знак при x = 1. Следовательно, f возрастает на (−∞; 1), убывает на (1; +∞)."},{"n":10,"level":"A","text":"Исследуйте монотонность функции f (x) = −2(x + 1)2 + 3.","answer":"Возрастает: (−∞; −1); убывает: (−1; +∞).","solution":"f ′ (x) = −4(x + 1); производная меняет знак при x = −1. Следовательно, f возрастает на (−∞; −1), убывает на (−1; +∞)."},{"n":11,"level":"A","text":"Исследуйте монотонность функции f (x) = 2x2 − 4.","answer":"Возрастает: (0; +∞); убывает: (−∞; 0).","solution":"f ′ (x) = 4x; производная меняет знак при x = 0. Следовательно, f возрастает на (0; +∞), убывает на (−∞; 0)."},{"n":12,"level":"A","text":"Исследуйте монотонность функции f (x) = −3(x − 3)2 + 1.","answer":"Возрастает: (−∞; 3); убывает: (3; +∞).","solution":"f ′ (x) = −6(x − 3); производная меняет знак при x = 3. Следовательно, f возрастает на (−∞; 3), убывает на (3; +∞)."},{"n":13,"level":"A","text":"Исследуйте f (x) = x3. Важно ли, что f ′ (0) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3x2; знак производной положителен для всех x ̸= 0 и равен нулю лишь при x = 0. Поэтому направление изменения сохраняется на всей R."},{"n":14,"level":"A","text":"Исследуйте f (x) = (x − 1)3. Важно ли, что f ′ (1) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x − 1)2; знак производной положителен для всех x ̸= 1 и равен нулю лишь при x = 1. Поэтому направление изменения сохраняется на всей R."},{"n":15,"level":"A","text":"Исследуйте f (x) = −(x + 2)3. Важно ли, что f ′ (−2) = 0?","answer":"Убывает на R.","solution":"f ′ (x) = −3(x + 2)2; знак производной отрицателен для всех x ̸= −2 и равен нулю лишь при x = −2. Поэтому направление изменения сохраняется на всей R."},{"n":16,"level":"A","text":"Исследуйте f (x) = (x − 3)3. Важно ли, что f ′ (3) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x − 3)2; знак производной положителен для всех x ̸= 3 и равен нулю лишь при x = 3. Поэтому направление изменения сохраняется на всей R."},{"n":17,"level":"A","text":"Исследуйте f (x) = (x + 1)3. Важно ли, что f ′ (−1) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x + 1)2; знак производной положителен для всех x ̸= −1 и равен нулю лишь при x = −1. Поэтому направление изменения сохраняется на всей R."},{"n":18,"level":"A","text":"Исследуйте f (x) = −(x − 2)3. Важно ли, что f ′ (2) = 0?","answer":"Убывает на R.","solution":"f ′ (x) = −3(x−2)2; знак производной отрицателен для всех x ̸= 2 и равен нулю лишь при x = 2. Поэтому направление изменения сохраняется на всей R."},{"n":19,"level":"B","text":"Исследуйте монотонность функции f (x) = (x − 4)2 + 3.","answer":"Возрастает: (4; +∞); убывает: (−∞; 4).","solution":"f ′ (x) = 2(x − 4); производная меняет знак при x = 4. Следовательно, f возрастает на (4; +∞), убывает на (−∞; 4)."},{"n":20,"level":"B","text":"Исследуйте монотонность функции f (x) = −(x + 4)2 + 1.","answer":"Возрастает: (−∞; −4); убывает: (−4; +∞).","solution":"f ′ (x) = −2(x + 4); производная меняет знак при x = −4. Следовательно, f возрастает на (−∞; −4), убывает на (−4; +∞)."},{"n":21,"level":"B","text":"Исследуйте монотонность функции f (x) = 2(x − 3)2 − 1.","answer":"Возрастает: (3; +∞); убывает: (−∞; 3).","solution":"f ′ (x) = 4(x − 3); производная меняет знак при x = 3. Следовательно, f возрастает на (3; +∞), убывает на (−∞; 3)."},{"n":22,"level":"B","text":"Исследуйте монотонность функции f (x) = −2(x − 2)2 + 5.","answer":"Возрастает: (−∞; 2); убывает: (2; +∞).","solution":"f ′ (x) = −4(x − 2); производная меняет знак при x = 2. Следовательно, f возрастает на (−∞; 2), убывает на (2; +∞)."},{"n":23,"level":"B","text":"Исследуйте монотонность функции f (x) = (x + 5)2 − 2.","answer":"Возрастает: (−5; +∞); убывает: (−∞; −5).","solution":"f ′ (x) = 2(x + 5); производная меняет знак при x = −5. Следовательно, f возрастает на (−5; +∞), убывает на (−∞; −5)."},{"n":24,"level":"B","text":"Исследуйте монотонность функции f (x) = −3(x + 3)2 + 4.","answer":"Возрастает: (−∞; −3); убывает: (−3; +∞).","solution":"f ′ (x) = −6(x + 3); производная меняет знак при x = −3. Следовательно, f возрастает на (−∞; −3), убывает на (−3; +∞)."},{"n":25,"level":"B","text":"Исследуйте монотонность функции f (x) = 3(x − 1)2 − 1.","answer":"Возрастает: (1; +∞); убывает: (−∞; 1).","solution":"f ′ (x) = 6(x − 1); производная меняет знак при x = 1. Следовательно, f возрастает на (1; +∞), убывает на (−∞; 1)."},{"n":26,"level":"B","text":"Исследуйте монотонность функции f (x) = 2(x + 2)2. ","answer":"Возрастает: (−2; +∞); убывает: (−∞; −2).","solution":"f ′ (x) = 4(x + 2); производная меняет знак при x = −2. Следовательно, f возрастает на (−2; +∞), убывает на (−∞; −2)."},{"n":27,"level":"B","text":"Укажите промежутки возрастания и убывания f (x) = x3 − 3x.","answer":"Возрастает: (−∞; −1), (1; +∞); убывает: (−1; 1).","solution":"f ′ (x) = 3(x2 − 1) = 3(x − 1)(x + 1). Нули производной: −1 и 1. Знак по промежуткам даёт ответ."},{"n":28,"level":"B","text":"Укажите промежутки возрастания и убывания f (x) = x3 − 12x.","answer":"Возрастает: (−∞; −2), (2; +∞); убывает: (−2; 2).","solution":"f (x) = 3(x − 4) = 3(x − 2)(x + 2). Нули производной: −2 и 2. Знак по промежуткам ′ 2 даёт ответ."},{"n":29,"level":"B","text":"Укажите промежутки возрастания и убывания f (x) = x3 − 27x.","answer":"Возрастает: (−∞; −3), (3; +∞); убывает: (−3; 3).","solution":"f ′ (x) = 3(x2 − 9) = 3(x − 3)(x + 3). Нули производной: −3 и 3. Знак по промежуткам даёт ответ."},{"n":30,"level":"B","text":"Укажите промежутки возрастания и убывания f (x) = −x3 + 3x.","answer":"Возрастает: (−1; 1); убывает: (−∞; −1), (1; +∞).","solution":"f ′ (x) = −3(x2 −1) = −3(x−1)(x+1). Нули производной: −1 и 1. Знак по промежуткам даёт ответ."},{"n":31,"level":"B","text":"Укажите промежутки возрастания и убывания f (x) = −x3 + 12x.","answer":"Возрастает: (−2; 2); убывает: (−∞; −2), (2; +∞).","solution":"f (x) = −3(x −4) = −3(x−2)(x+2). Нули производной: −2 и 2. Знак по промежуткам ′ 2 даёт ответ."},{"n":32,"level":"B","text":"Укажите промежутки возрастания и убывания f (x) = x3 − 48x.","answer":"Возрастает: (−∞; −4), (4; +∞); убывает: (−4; 4).","solution":"f ′ (x) = 3(x2 − 16) = 3(x − 4)(x + 4). Нули производной: −4 и 4. Знак по промежуткам даёт ответ."},{"n":33,"level":"B","text":"Исследуйте f (x) = (x + 4)3. Важно ли, что f ′ (−4) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x + 4)2; знак производной положителен для всех x ̸= −4 и равен нулю лишь при x = −4. Поэтому направление изменения сохраняется на всей R."},{"n":34,"level":"B","text":"Исследуйте f (x) = −(x − 4)3. Важно ли, что f ′ (4) = 0?","answer":"Убывает на R.","solution":"f ′ (x) = −3(x−4)2; знак производной отрицателен для всех x ̸= 4 и равен нулю лишь при x = 4. Поэтому направление изменения сохраняется на всей R."},{"n":35,"level":"B","text":"Исследуйте f (x) = (x − 5)3. Важно ли, что f ′ (5) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x − 5)2; знак производной положителен для всех x ̸= 5 и равен нулю лишь при x = 5. Поэтому направление изменения сохраняется на всей R."},{"n":36,"level":"B","text":"Исследуйте f (x) = −(x + 5)3. Важно ли, что f ′ (−5) = 0?","answer":"Убывает на R.","solution":"f ′ (x) = −3(x + 5)2; знак производной отрицателен для всех x ̸= −5 и равен нулю лишь при x = −5. Поэтому направление изменения сохраняется на всей R."},{"n":37,"level":"C","text":"Известно: f ′ (x) = (x+3)(x−2) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−∞; −3), (2; +∞); убывает: (−3; 2).","solution":"f (x) = (x + 3)(x − 2). Нули x = −3, x = 2. Точки делят прямую на три интервала; ′ знаки множителей определяют направление."},{"n":38,"level":"C","text":"Известно: f ′ (x) = −(x + 1)(x − 4) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−1; 4); убывает: (−∞; −1), (4; +∞).","solution":"f ′ (x) = −(x + 1)(x − 4). Нули x = −1, x = 4. Точки делят прямую на три интервала; знаки множителей определяют направление."},{"n":39,"level":"C","text":"Известно: f ′ (x) = (x)(x − 5) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−∞; 0), (5; +∞); убывает: (0; 5).","solution":"f ′ (x) = (x)(x − 5). Нули x = 0, x = 5. Точки делят прямую на три интервала; знаки множителей определяют направление."},{"n":40,"level":"C","text":"Известно: f ′ (x) = −(x + 4)(x − 1) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−4; 1); убывает: (−∞; −4), (1; +∞).","solution":"f ′ (x) = −(x + 4)(x − 1). Нули x = −4, x = 1. Точки делят прямую на три интервала; знаки множителей определяют направление."},{"n":41,"level":"C","text":"Найдите промежутки монотонности f (x) = x + x1 с учётом области определения.","answer":"Возрастает: (−∞; −1), (1; +∞); убывает: (−1; 0), (0; 1).","solution":"Область определения: x ̸= 0. ′ = (x−1)(x+1) f (x) = 1 − x12 x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±1."},{"n":42,"level":"C","text":"Найдите промежутки монотонности f (x) = x+ x4 +3 с учётом области определения.","answer":"Возрастает: (−∞; −2), (2; +∞); убывает: (−2; 0), (0; 2).","solution":"Область определения: x ̸= 0. f ′ (x) = 1 − x42 = (x−2)(x+2) x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±2."},{"n":43,"level":"C","text":"Найдите промежутки монотонности f (x) = x+ x9 −2 с учётом области определения.","answer":"Возрастает: (−∞; −3), (3; +∞); убывает: (−3; 0), (0; 3).","solution":"Область определения: x ̸= 0. ′ = (x−3)(x+3) f (x) = 1 − x92 x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±3."},{"n":44,"level":"C","text":"Найдите промежутки монотонности f (x) = x + 5 с учётом области x + 16 определения.","answer":"Возрастает: (−∞; −4), (4; +∞); убывает: (−4; 0), (0; 4).","solution":"Область определения: x ̸= 0. ′ = (x−4)(x+4) f (x) = 1 − x162 x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±4."},{"n":45,"level":"C","text":"Исследуйте f (x) = ln x − x при x > 0.","answer":"Возрастает: (0; 1); убывает: (1; +∞).","solution":"D(f ) = (0; +∞); f ′ (x) = x1 − 1. Знак положителен при 0 < x < 11 и отрицателен при x > 11. "},{"n":46,"level":"C","text":"Исследуйте f (x) = ln x − 2x при x > 0.","answer":"Возрастает: (0; 21 ); убывает: ( 12; +∞).","solution":"D(f ) = (0; +∞); f ′ (x) = x1 − 2. Знак положителен при 0 < x < 21 и отрицателен при x > 12. "},{"n":47,"level":"C","text":"Для f (x) = x2 −2x+2 найдите касательную при x0 = 0 и промежутки монотонности.","answer":"Касательная y = −2x + 2; возрастает (1; +∞), убывает (−∞; 1).","solution":"f (0) = 2, f ′ (x) = 2x − 2, f ′ (0) = −2, касательная y = −2x + 2. По знаку 2(x − 1) функция убывает до 1 и возрастает после."},{"n":48,"level":"C","text":"Для f (x) = x2 +4x+5 найдите касательную при x0 = 0 и промежутки монотонности. Контроль Проверка понимания","answer":"Касательная y = 4x + 5; возрастает (−2; +∞), убывает (−∞; −2).","solution":"f (0) = 5, f ′ (x) = 2x + 4, f ′ (0) = 4, касательная y = 4x + 5. По знаку 2(x + 2) функция убывает до −2 и возрастает после. Контроль Проверка понимания"},{"n":49,"level":"Контроль","text":"Ученик утверждает: «Если f (x) < 0 на интервале, то функция убывает». Приведите контрпример.","answer":"Например, f (x) = x на (−2; −1): значения отрицательны, функция возрастает.","solution":"Для монотонности исследуется знак производной f ′ , а не знак f ."},{"n":50,"level":"Контроль","text":"Ученик вычислил f ′ (x) = 3x2 и заявил, что f возрастает только на (−∞; 0) и (0; +∞), но не на R. Исправьте вывод.","answer":"f возрастает на всей R.","solution":"Производная неотрицательна всюду и равна нулю только в одной точке; это не препятствует возрастанию x3. "},{"n":51,"level":"Контроль","text":"Исследуя f (x) = x + x4, ученик записал убывание на (−2; 2). Объясните ошибку и исправьте.","answer":"Убывает на (−2; 0) и (0; 2).","solution":"x = 0 исключён из области определения, поэтому через эту точку промежуток монотонности продолжать нельзя."},{"n":52,"level":"Контроль","text":"Производная имеет знаки: f ′ > 0 при x < −1 и x > 3, f ′ < 0 при −1 < x < 3. Укажите промежутки монотонности.","answer":"Возрастает на (−∞; −1) и (3; +∞); убывает на (−1; 3).","solution":"Знак + соответствует возрастанию, знак − — убыванию."},{"n":53,"level":"Контроль","text":"На (−3; 2) производная отрицательна, а касательная в некоторой точке имеет положительный наклон. Возможна ли такая ситуация при дифференцируемой функции?","answer":"Невозможна.","solution":"Угловой коэффициент касательной равен f ′ (x0 ); он должен быть отрицателен в каждой внутренней точке интервала."},{"n":54,"level":"Контроль","text":"Для f (x) = (x − 2)3 производная равна нулю в точке 2. Обязательно ли в ней меняется направление изменения функции?","answer":"Нет; функция возрастает на R.","solution":"f ′ (x) = 3(x − 2)2 ≥ 0, знак при переходе через 2 сохраняется. Рекомендация к проверке За полный ответ на вычислительную задачу учитывайте три шага: нахождение f ′ , определение её знака на допустимых интервалах, интерпретация результата. При ошибке в направлении монотонности сначала проверьте знак производной и область определения."}],"strong":[{"n":1,"level":"A","text":"Найдите знак f ′ (x) и промежутки монотонности f (x) = 2(x − 2)2. ","answer":"Возрастает: (2; +∞); убывает: (−∞; 2).","solution":"f ′ (x) = 4(x − 2); производная меняет знак при x = 2. Следовательно, f возрастает на (2; +∞), убывает на (−∞; 2)."},{"n":2,"level":"A","text":"Найдите знак f ′ (x) и промежутки монотонности f (x) = −2(x + 3)2 + 2.","answer":"Возрастает: (−∞; −3); убывает: (−3; +∞).","solution":"f ′ (x) = −4(x + 3); производная меняет знак при x = −3. Следовательно, f возрастает на (−∞; −3), убывает на (−3; +∞)."},{"n":3,"level":"A","text":"Найдите знак f ′ (x) и промежутки монотонности f (x) = 3(x + 1)2 − 4.","answer":"Возрастает: (−1; +∞); убывает: (−∞; −1).","solution":"f ′ (x) = 6(x + 1); производная меняет знак при x = −1. Следовательно, f возрастает на (−1; +∞), убывает на (−∞; −1)."},{"n":4,"level":"A","text":"Найдите знак f ′ (x) и промежутки монотонности f (x) = (x − 5)2 + 1.","answer":"Возрастает: (5; +∞); убывает: (−∞; 5).","solution":"f ′ (x) = 2(x − 5); производная меняет знак при x = 5. Следовательно, f возрастает на (5; +∞), убывает на (−∞; 5)."},{"n":5,"level":"A","text":"Исследуйте f (x) = x3. Важно ли, что f ′ (0) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3x2; знак производной положителен для всех x ̸= 0 и равен нулю лишь при x = 0. Поэтому направление изменения сохраняется на всей R."},{"n":6,"level":"A","text":"Исследуйте f (x) = −(x − 2)3. Важно ли, что f ′ (2) = 0?","answer":"Убывает на R.","solution":"f ′ (x) = −3(x−2)2; знак производной отрицателен для всех x ̸= 2 и равен нулю лишь при x = 2. Поэтому направление изменения сохраняется на всей R."},{"n":7,"level":"A","text":"Исследуйте f (x) = (x + 3)3. Важно ли, что f ′ (−3) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x + 3)2; знак производной положителен для всех x ̸= −3 и равен нулю лишь при x = −3. Поэтому направление изменения сохраняется на всей R."},{"n":8,"level":"A","text":"Исследуйте f (x) = (x − 5)3. Важно ли, что f ′ (5) = 0?","answer":"Возрастает на R.","solution":"f ′ (x) = 3(x − 5)2; знак производной положителен для всех x ̸= 5 и равен нулю лишь при x = 5. Поэтому направление изменения сохраняется на всей R."},{"n":9,"level":"A","text":"Известно: f ′ (x) = (x + 2)(x − 2) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−∞; −2), (2; +∞); убывает: (−2; 2).","solution":"f ′ (x) = (x + 2)(x − 2). Нули x = −2, x = 2. Точки делят прямую на три интервала; знаки множителей определяют направление."},{"n":10,"level":"A","text":"Известно: f ′ (x) = −(x + 3)(x − 1) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−3; 1); убывает: (−∞; −3), (1; +∞).","solution":"f (x) = −(x + 3)(x − 1). Нули x = −3, x = 1. Точки делят прямую на три интервала; ′ знаки множителей определяют направление."},{"n":11,"level":"A","text":"Известно: f ′ (x) = (x−1)(x−4) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−∞; 1), (4; +∞); убывает: (1; 4).","solution":"f (x) = (x − 1)(x − 4). Нули x = 1, x = 4. Точки делят прямую на три интервала; знаки ′ множителей определяют направление."},{"n":12,"level":"A","text":"Известно: f ′ (x) = −(x + 4)(x) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−4; 0); убывает: (−∞; −4), (0; +∞).","solution":"f (x) = −(x + 4)(x). Нули x = −4, x = 0. Точки делят прямую на три интервала; знаки ′ множителей определяют направление."},{"n":13,"level":"B","text":"Исследуйте монотонность f (x) = (x2 − 1)2. Обоснуйте знаки производной.","answer":"Возрастает: (−1; 0), (1; +∞); убывает: (−∞; −1), (0; 1).","solution":"f (x) = 4x(x − 1)(x + 1). Нули: −1, 0, 1; знаки производной слева направо: −, +, −, +. ′ Сформулированные интервалы следуют из таблицы знаков."},{"n":14,"level":"B","text":"Исследуйте монотонность f (x) = (x2 − 4)2. Обоснуйте знаки производной.","answer":"Возрастает: (−2; 0), (2; +∞); убывает: (−∞; −2), (0; 2).","solution":"f ′ (x) = 4x(x − 2)(x + 2). Нули: −2, 0, 2; знаки производной слева направо: −, +, −, +. Сформулированные интервалы следуют из таблицы знаков."},{"n":15,"level":"B","text":"Исследуйте монотонность f (x) = (x2 − 9)2. Обоснуйте знаки производной.","answer":"Возрастает: (−3; 0), (3; +∞); убывает: (−∞; −3), (0; 3).","solution":"f (x) = 4x(x − 3)(x + 3). Нули: −3, 0, 3; знаки производной слева направо: −, +, −, +. ′ Сформулированные интервалы следуют из таблицы знаков."},{"n":16,"level":"B","text":"Исследуйте монотонность f (x) = (x2 − 16)2. Обоснуйте знаки производной.","answer":"Возрастает: (−4; 0), (4; +∞); убывает: (−∞; −4), (0; 4).","solution":"f (x) = 4x(x − 4)(x + 4). Нули: −4, 0, 4; знаки производной слева направо: −, +, −, +. ′ Сформулированные интервалы следуют из таблицы знаков."},{"n":17,"level":"B","text":"Исследуйте монотонность f (x) = (x2 − 25)2. Обоснуйте знаки производной.","answer":"Возрастает: (−5; 0), (5; +∞); убывает: (−∞; −5), (0; 5).","solution":"f ′ (x) = 4x(x − 5)(x + 5). Нули: −5, 0, 5; знаки производной слева направо: −, +, −, +. Сформулированные интервалы следуют из таблицы знаков."},{"n":18,"level":"B","text":"Найдите промежутки монотонности f (x) = x+ x1 −4 с учётом области определения.","answer":"Возрастает: (−∞; −1), (1; +∞); убывает: (−1; 0), (0; 1).","solution":"Область определения: x ̸= 0. ′ = (x−1)(x+1) f (x) = 1 − x12 x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±1."},{"n":19,"level":"B","text":"Найдите промежутки монотонности f (x) = x+ x4 +1 с учётом области определения.","answer":"Возрастает: (−∞; −2), (2; +∞); убывает: (−2; 0), (0; 2).","solution":"Область определения: x ̸= 0. f ′ (x) = 1 − x42 = (x−2)(x+2) x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±2."},{"n":20,"level":"B","text":"Найдите промежутки монотонности f (x) = x + x9 с учётом области определения.","answer":"Возрастает: (−∞; −3), (3; +∞); убывает: (−3; 0), (0; 3).","solution":"Область определения: x ̸= 0. f ′ (x) = 1 − x92 = (x−3)(x+3) x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±3."},{"n":21,"level":"B","text":"Найдите промежутки монотонности f (x) = x − 2 с учётом области x + 16 определения.","answer":"Возрастает: (−∞; −4), (4; +∞); убывает: (−4; 0), (0; 4).","solution":"Область определения: x ̸= 0. ′ = (x−4)(x+4) f (x) = 1 − x162 x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±4."},{"n":22,"level":"B","text":"Найдите промежутки монотонности f (x) = x + 3 с учётом области x + 25 определения.","answer":"Возрастает: (−∞; −5), (5; +∞); убывает: (−5; 0), (0; 5).","solution":"Область определения: x ̸= 0. ′ = (x−5)(x+5) f (x) = 1 − x252 x2. При x ̸= 0 знаменатель положителен, знак числителя определяется точками ±5."},{"n":23,"level":"B","text":"Исследуйте монотонность f (x) = (x − 1)3 − 3(x − 1).","answer":"Возрастает: (−∞; 0), (2; +∞); убывает: (0; 2).","solution":"f ′ (x) = 3((x − 1)2 − 1) = 3(x)(x − 2). Знак + вне корней и − между ними."},{"n":24,"level":"B","text":"Исследуйте монотонность f (x) = x3 − 12(x).","answer":"Возрастает: (−∞; −2), (2; +∞); убывает: (−2; 2).","solution":"f (x) = 3(x − 4) = 3(x + 2)(x − 2). Знак + вне корней и − между ними. ′ 2"},{"n":25,"level":"B","text":"Исследуйте монотонность f (x) = (x + 2)3 − 27(x + 2).","answer":"Возрастает: (−∞; −5), (1; +∞); убывает: (−5; 1).","solution":"f ′ (x) = 3((x + 2)2 − 9) = 3(x + 5)(x − 1). Знак + вне корней и − между ними."},{"n":26,"level":"B","text":"Исследуйте монотонность f (x) = (x + 3)3 − 3(x + 3).","answer":"Возрастает: (−∞; −4), (−2; +∞); убывает: (−4; −2).","solution":"f ′ (x) = 3((x + 3)2 − 1) = 3(x + 4)(x + 2). Знак + вне корней и − между ними."},{"n":27,"level":"B","text":"Известно: f ′ (x) = (x+2)2 (x−3) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (3; +∞); убывает: (−∞; 3).","solution":"f ′ (x) = (x + 2)2 (x − 3). Нули x = −2, x = 3. Квадратный множитель не меняет знак; знак задаёт (x − 3)."},{"n":28,"level":"B","text":"Известно: f ′ (x) = −(x + 3)2 (x − 2) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−∞; 2); убывает: (2; +∞).","solution":"f ′ (x) = −(x + 3)2 (x − 2). Нули x = −3, x = 2. Квадратный множитель не меняет знак; знак задаёт (x − 2)."},{"n":29,"level":"B","text":"Известно: f ′ (x) = (x−1)(x−5) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−∞; 1), (5; +∞); убывает: (1; 5).","solution":"f (x) = (x − 1)(x − 5). Нули x = 1, x = 5. Точки делят прямую на три интервала; знаки ′ множителей определяют направление."},{"n":30,"level":"B","text":"Известно: f ′ (x) = −(x + 4)(x − 2) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−4; 2); убывает: (−∞; −4), (2; +∞).","solution":"f ′ (x) = −(x + 4)(x − 2). Нули x = −4, x = 2. Точки делят прямую на три интервала; знаки множителей определяют направление."},{"n":31,"level":"C","text":"Для f (x) = (x + 2)3 − 3(x + 2) + 2 найдите интервалы монотонности. Объясните влияние сдвига графика.","answer":"Возрастает (−∞; −3), (−1; +∞); убывает (−3; −1). Вертикальный сдвиг на 2 не меняет производную.","solution":"f ′ (x) = 3[((x + 2))2 − 1]. Нули x = −3 и x = −1. Производная положительна снаружи отрезка между ними и отрицательна внутри."},{"n":32,"level":"C","text":"Для f (x) = (x − 3)3 − 12(x − 3) + 2 найдите интервалы монотонности. Объясните влияние сдвига графика.","answer":"Возрастает (−∞; 1), (5; +∞); убывает (1; 5). Вертикальный сдвиг на 2 не меняет производную.","solution":"f ′ (x) = 3[((x − 3))2 − 4]. Нули x = 1 и x = 5. Производная положительна снаружи отрезка между ними и отрицательна внутри."},{"n":33,"level":"C","text":"Для f (x) = (x + 1)3 − 27(x + 1) + 2 найдите интервалы монотонности. Объясните влияние сдвига графика.","answer":"Возрастает (−∞; −4), (2; +∞); убывает (−4; 2). Вертикальный сдвиг на 2 не меняет производную.","solution":"f ′ (x) = 3[((x + 1))2 − 9]. Нули x = −4 и x = 2. Производная положительна снаружи отрезка между ними и отрицательна внутри."},{"n":34,"level":"C","text":"Для f (x) = (x − 2)3 − 48(x − 2) + 2 найдите интервалы монотонности. Объясните влияние сдвига графика.","answer":"Возрастает (−∞; −2), (6; +∞); убывает (−2; 6). Вертикальный сдвиг на 2 не меняет производную.","solution":"f ′ (x) = 3[((x − 2))2 − 16]. Нули x = −2 и x = 6. Производная положительна снаружи отрезка между ними и отрицательна внутри."},{"n":35,"level":"C","text":"Для f (x) = (x + 4)3 − 75(x + 4) + 2 найдите интервалы монотонности. Объясните влияние сдвига графика.","answer":"Возрастает (−∞; −9), (1; +∞); убывает (−9; 1). Вертикальный сдвиг на 2 не меняет производную.","solution":"f ′ (x) = 3[((x + 4))2 − 25]. Нули x = −9 и x = 1. Производная положительна снаружи отрезка между ними и отрицательна внутри."},{"n":36,"level":"C","text":"Дана производная f ′ (x) = (x + 4)(x − 1). Без восстановления f постройте таблицу знаков и сделайте вывод о монотонности.","answer":"Возрастает: (−∞; −4), (1; +∞); убывает: (−4; 1).","solution":"Отметим корни −4 и 1; при положительном коэффициенте знак +, −, +, при отрицательном −, +, −."},{"n":37,"level":"C","text":"Дана производная f ′ (x) = −(x + 3)(x − 3). Без восстановления f постройте таблицу знаков и сделайте вывод о монотонности.","answer":"Возрастает: (−3; 3); убывает: (−∞; −3), (3; +∞).","solution":"Отметим корни −3 и 3; при положительном коэффициенте знак +, −, +, при отрицательном −, +, −."},{"n":38,"level":"C","text":"Дана производная f ′ (x) = (x + 2)(x − 5). Без восстановления f постройте таблицу знаков и сделайте вывод о монотонности.","answer":"Возрастает: (−∞; −2), (5; +∞); убывает: (−2; 5).","solution":"Отметим корни −2 и 5; при положительном коэффициенте знак +, −, +, при отрицательном −, +, −."},{"n":39,"level":"C","text":"Дана производная f ′ (x) = −(x − 1)(x − 4). Без восстановления f постройте таблицу знаков и сделайте вывод о монотонности.","answer":"Возрастает: (1; 4); убывает: (−∞; 1), (4; +∞).","solution":"Отметим корни 1 и 4; при положительном коэффициенте знак +, −, +, при отрицательном −, +, −."},{"n":40,"level":"C","text":"Известно: f ′ (x) = (x+4)2 (x+1) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (−1; +∞); убывает: (−∞; −1).","solution":"f ′ (x) = (x + 4)2 (x + 1). Нули x = −4, x = −1. Квадратный множитель не меняет знак; знак задаёт (x + 1)."},{"n":41,"level":"C","text":"Известно: f ′ (x) = (x+2)2 (x−4) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (4; +∞); убывает: (−∞; 4).","solution":"f ′ (x) = (x + 2)2 (x − 4). Нули x = −2, x = 4. Квадратный множитель не меняет знак; знак задаёт (x − 4)."},{"n":42,"level":"C","text":"Известно: f ′ (x) = (x−1)2 (x−5) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (5; +∞); убывает: (−∞; 5).","solution":"f ′ (x) = (x − 1)2 (x − 5). Нули x = 1, x = 5. Квадратный множитель не меняет знак; знак задаёт (x − 5)."},{"n":43,"level":"C","text":"Известно: f ′ (x) = x2 (x − 4) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (4; +∞); убывает: (−∞; 4).","solution":"f ′ (x) = x2 (x − 4). Нули x = 0, x = 4. Квадратный множитель не меняет знак; знак задаёт (x − 4)."},{"n":44,"level":"C","text":"Известно: f ′ (x) = (x−2)2 (x−6) для всех x ∈ R. Определите промежутки возрастания и убывания f .","answer":"Возрастает: (6; +∞); убывает: (−∞; 6).","solution":"f ′ (x) = (x − 2)2 (x − 6). Нули x = 2, x = 6. Квадратный множитель не меняет знак; знак задаёт (x − 6)."},{"n":45,"level":"C","text":"Докажите с помощью производной, что f (x) = x3 + 3x строго возрастает на R, и укажите знак наклона любой касательной.","answer":"Строго возрастает на R; наклон каждой касательной положителен.","solution":"f ′ (x) = 3x2 +3 > 0 при любом действительном x. Значит, функция строго возрастает, и k = f ′ (x0 ) > 0."},{"n":46,"level":"C","text":"Докажите с помощью производной, что f (x) = x3 + 12x строго возрастает на R, и укажите знак наклона любой касательной.","answer":"Строго возрастает на R; наклон каждой касательной положителен.","solution":"f ′ (x) = 3x2 + 12 > 0 при любом действительном x. Значит, функция строго возрастает, и k = f ′ (x0 ) > 0."},{"n":47,"level":"C","text":"Докажите с помощью производной, что f (x) = x3 + 27x строго возрастает на R, и укажите знак наклона любой касательной.","answer":"Строго возрастает на R; наклон каждой касательной положителен.","solution":"f ′ (x) = 3x2 + 27 > 0 при любом действительном x. Значит, функция строго возрастает, и k = f ′ (x0 ) > 0."},{"n":48,"level":"C","text":"Докажите с помощью производной, что f (x) = x3 + 48x строго возрастает на R, и укажите знак наклона любой касательной. Контроль Проверка понимания","answer":"Строго возрастает на R; наклон каждой касательной положителен.","solution":"f ′ (x) = 3x2 + 48 > 0 при любом действительном x. Значит, функция строго возрастает, и k = f ′ (x0 ) > 0. Контроль Проверка понимания"},{"n":49,"level":"Контроль","text":"Ученик считает: если f ′ (a) = 0, функция обязательно меняет направление при a. Опровергните утверждение двумя разными функциями.","answer":"Например, x3 и (x − 1)3 сохраняют возрастание при нулевой производной.","solution":"3x2 и 3(x − 1)2 неотрицательны и имеют одиночный нуль, поэтому знак не меняется."},{"n":50,"level":"Контроль","text":"Известно, что на (−4; 0) выполнено f ′ > 0, а на (0; 3) — f ′ < 0. Можно ли без сведений о непрерывности в 0 сделать вывод, что f меняет направление на всём (−4; 3)?","answer":"На указанных частях: возрастает слева, убывает справа. Для поведения через 0 нужна информация о функции в этой точке.","solution":"Сам знак производной на двух непересекающихся интервалах не гарантирует наличие значения или непрерывность функции в точке 0."},{"n":51,"level":"Контроль","text":"Для f (x) = x + x9 студент объединил интервалы (−3; 0) и (0; 3) в один интервал убывания. Оцените корректность.","answer":"Объединять в один промежуток монотонности нельзя: 0 ∈ / D(f ).","solution":"f ′ = 1 − 9/x2 < 0 при 0 < |x| < 3, но в 0 функция не определена."},{"n":52,"level":"Контроль","text":"Производная задана формулой f ′ (x) = (x + 1)2 (x − 4). Объясните, почему нуль в −1 не разделяет два интервала с разным направлением изменения.","answer":"Функция убывает при x < 4 (кроме изолированной точки −1 со значением производной 0) и возрастает при x > 4.","solution":"Квадрат (x + 1)2 неотрицателен и не меняет знак; направление определяет множитель (x − 4)."},{"n":53,"level":"Контроль","text":"При исследовании f (x) = ln x − 2x ученик получил f ′ = x1 − 2, но записал интервал возрастания (−∞; 21 ). Исправьте.","answer":"Возрастает на (0; 12 ); убывает на ( 12; +∞).","solution":"Область определения логарифма x > 0. Положительный знак производной реализуется лишь на (0; 1/2)."},{"n":54,"level":"Контроль","text":"Функция дифференцируема на R, причём f ′ (x) = 3(x − 2)2 + 1. Можно ли по этому факту гарантировать положительный наклон любой касательной и возрастание на всей прямой?","answer":"Да: f ′ (x) > 0 для всех x.","solution":"Квадрат неотрицателен, значит 3(x − 2)2 + 1 ≥ 1. Наклоны касательных строго положительны, функция строго возрастает. Рекомендация к проверке За полный ответ на вычислительную задачу учитывайте три шага: нахождение f ′ , определение её знака на допустимых интервалах, интерпретация результата. При ошибке в направлении монотонности сначала проверьте знак производной и область определения."}]}},"9a_l18":{"lines":{"standard":[{"n":1,"level":"A","text":"Вычислите 196 − 81. √ √","answer":"5.","solution":"14 − 9 = 5."},{"n":2,"level":"A","text":"Вычислите 225 + 64. √","answer":"23.","solution":"15 + 8 = 23. √"},{"n":3,"level":"A","text":"Вычислите 0,81 · 10. √","answer":"9.","solution":"0,81 = 0,9, значит 0,9 · 10 = 9. √"},{"n":4,"level":"A","text":"Сравните 65 и 8. √ √","answer":"65 > 8.","solution":"65 > 64 = 82, обе величины неотрицательны. √ √ √"},{"n":5,"level":"A","text":"Сравните 3 7 и 60. √","answer":"3 7 > 60.","solution":"(3 7)2 = 63 > 60; оба числа положительны. √"},{"n":6,"level":"A","text":"Сравните 80 и 9.","answer":"80 < 9.","solution":"80 < 81 = 92. "},{"n":7,"level":"A","text":"Округлите число 24,376 до сотых.","answer":"24,38.","solution":"Третья цифра после запятой равна 6, поэтому сотые увеличиваем на единицу."},{"n":8,"level":"A","text":"Округлите число 0,04896 до тысячных.","answer":"0,049.","solution":"В разряде десятитысячных стоит 9; тысячные увеличиваем с 8 до 9."},{"n":9,"level":"A","text":"Округлите 1,995 до сотых с обычным правилом округления.","answer":"2,00.","solution":"Цифра тысячных 5 вызывает перенос через сотые и десятые."},{"n":10,"level":"A","text":"Число 12,48 заменили на 12,5. Найдите абсолютную погрешность.","answer":"0,02.","solution":"|12,48 − 12,5| = 0,02."},{"n":11,"level":"A","text":"Точное значение 9,73, приближённое 9,7. Найдите абсолютную погрешность.","answer":"0,03.","solution":"|9,73 − 9,7| = 0,03."},{"n":12,"level":"A","text":"Число 2,995 заменили на 3,00. Найдите абсолютную погрешность.","answer":"0,005.","solution":"|3,000 − 2,995| = 0,005."},{"n":13,"level":"A","text":"Запишите 0,0000048 в стандартном виде.","answer":"4,8 · 10−6. ","solution":"Переносим запятую на шесть позиций вправо; показатель отрицателен."},{"n":14,"level":"A","text":"Запишите 6 700 000 в стандартном виде.","answer":"6,7 · 106. ","solution":"Порядок записи — 106. "},{"n":15,"level":"A","text":"Переведите 2,4 км в метры.","answer":"2400 м.","solution":"2,4 · 1000 = 2400 м."},{"n":16,"level":"A","text":"Выразите 45 минут в часах.","answer":"0,75 ч.","solution":"45/60 = 3/4 = 0,75 ч."},{"n":17,"level":"A","text":"После скидки 20% товар за 1500 руб. стоит сколько?","answer":"1200 руб..","solution":"1500 · 0,80 = 1200."},{"n":18,"level":"A","text":"После повышения на 15% цена 800 руб. станет какой? Основные алгоритмы и прикладные модели","answer":"920 руб..","solution":"800 · 1,15 = 920."},{"n":19,"level":"B","text":"Длина 4,00 м измерена с абсолютной погрешностью не более 0,02 м. Найдите относительную погрешность в процентах.","answer":"Не более 0,5%.","solution":"0,02/4,00 · 100% = 0,5%."},{"n":20,"level":"B","text":"Масса 250 г измерена с абсолютной погрешностью не более 2 г. Найдите относительную погрешность в процентах.","answer":"Не более 0,8%.","solution":"2/250 · 100% = 0,8%."},{"n":21,"level":"B","text":"Приближённое значение равно 160, максимальная абсолютная погрешность 0,8. Найдите относительную погрешность в процентах.","answer":"0,5%.","solution":"0,8/160 · 100% = 0,5%."},{"n":22,"level":"B","text":"Число 38,47 округлили до десятых. Найдите результат и абсолютную погрешность.","answer":"38,5; 0,03.","solution":"Округление даёт 38,5; |38,5 − 38,47| = 0,03."},{"n":23,"level":"B","text":"Вычислите (3,2 · 105 ) : (8 · 102 ).","answer":"4 · 102 = 400.","solution":"(3,2/8) · 105−2 = 0,4 · 103 = 400."},{"n":24,"level":"B","text":"Переведите 0,0075 км в сантиметры.","answer":"750 см.","solution":"0,0075 · 100000 = 750 см."},{"n":25,"level":"B","text":"Длительность процесса 3,6 · 10−3 с. Выразите её в миллисекундах.","answer":"3,6 мс.","solution":"1 с = 1000 мс, поэтому 3,6 · 10−3 · 103 = 3,6."},{"n":26,"level":"B","text":"За 50 минут автомобиль проехал 65 км. Найдите среднюю скорость в км/ч.","answer":"78 км/ч.","solution":"50 мин = 5/6 ч; 65 : (5/6) = 78."},{"n":27,"level":"B","text":"После скидки 25% товар стоит 2700 руб. Найдите первоначальную цену.","answer":"3600 руб..","solution":"0,75x = 2700, откуда x = 3600."},{"n":28,"level":"B","text":"После повышения на 12% цена стала 3360 руб. Найдите прежнюю цену.","answer":"3000 руб..","solution":"1,12x = 3360, x = 3000."},{"n":29,"level":"B","text":"Товар за 5000 руб. подешевел сначала на 10%, затем на 20% от новой цены. Найдите итоговую стоимость.","answer":"3600 руб..","solution":"5000 · 0,9 · 0,8 = 3600."},{"n":30,"level":"B","text":"Цена 2400 руб. выросла на 25%, затем снизилась на 20%. Найдите итоговую цену.","answer":"2400 руб..","solution":"2400 · 1,25 · 0,8 = 2400; цена вернулась к исходной."},{"n":31,"level":"B","text":"Тариф: 550 руб. за месяц включают 8 ГБ, сверх пакета — 45 руб. за ГБ. Использовано 12 ГБ. Сколько платить?","answer":"730 руб..","solution":"Превышение 12 − 8 = 4 ГБ; 550 + 45 · 4 = 730."},{"n":32,"level":"B","text":"Тариф А: 650 руб. без доплат. Тариф Б: 450 руб. и 35 руб. за каждую из 5 дополнительных единиц. Какой дешевле?","answer":"Б, на 25 руб..","solution":"Б: 450 + 5 · 35 = 625 руб.; 650 − 625 = 25 руб."},{"n":33,"level":"B","text":"Тариф: абонентская плата 720 руб., включено 15 ГБ, доплата 30 руб. за каждый дополнительный ГБ. Использовано ровно 15 ГБ. Цена?","answer":"720 руб..","solution":"Превышение ноль, доплата отсутствует."},{"n":34,"level":"B","text":"Тариф A: 500 руб. и 40 руб. за каждый ГБ сверх 10. При использовании 14 ГБ найдите полную цену.","answer":"660 руб..","solution":"Превышение 4 ГБ; 500 + 4 · 40 = 660."},{"n":35,"level":"B","text":"Раствор массой 750 г содержит 8% вещества. Сколько граммов вещества?","answer":"60 г.","solution":"750 · 0,08 = 60 г."},{"n":36,"level":"B","text":"Длина шага 0,72 м. Найдите пройденный путь за 6250 шагов в километрах. Перенос навыка и многошаговые задачи","answer":"4,5 км.","solution":"0,72 · 6250 = 4500 м = 4,5 км."},{"n":37,"level":"C","text":"В одной упаковке плитки — 1,8 м2. Для пола 29 м2 нужен запас 10%. Сколько целых упаковок купить?","answer":"18 упаковок.","solution":"Нужно 29 · 1,1 = 31,9 м2. 31,9/1,8 ≈ 17,72; покупаем 18 упаковок."},{"n":38,"level":"C","text":"Два тарифа при q ГБ сверх включённого пакета: A — 520 + 40q, Б — 680 + 20q руб. Найдите порог равенства.","answer":"q = 8 ГБ.","solution":"520 + 40q = 680 + 20q ⇒ 20q = 160 ⇒ q = 8."},{"n":39,"level":"C","text":"Для двух тарифов CA = 520 + 40q, CБ = 680 + 20q руб. какой выгоднее при q = 11?","answer":"Б на 60 руб..","solution":"CA = 960, CБ = 900, разница 60 руб."},{"n":40,"level":"C","text":"После скидки 15% к стоимости товара добавили доставку 350 руб., итог 2900 руб. Какова исходная цена?","answer":"3000 руб..","solution":"0,85x + 350 = 2900, поэтому x = 2550/0,85 = 3000."},{"n":41,"level":"C","text":"Приближённая масса 2,50 кг с абсолютной погрешностью не более 0,02 кг. Укажите промежуток допустимых истинных значений.","answer":"От 2,48 до 2,52 кг.","solution":"|m − 2,50| ≤ 0,02 ⇒ 2,48 ≤ m ≤ 2,52."},{"n":42,"level":"C","text":"По 180 км автомобиль ехал со скоростью 60 км/ч и ещё 180 км — со скоростью 90 км/ч. Найдите среднюю скорость.","answer":"72 км/ч.","solution":"Время: 180/60 + 180/90 = 3 + 2 = 5 ч. Путь 360 км, vср = 360/5 = 72."},{"n":43,"level":"C","text":"Товар за 4000 руб. сначала подорожал на 20%, затем подешевел на 20%. На сколько процентов цена отличается от начальной?","answer":"На 4% ниже.","solution":"1,2 · 0,8 = 0,96, итог 3840 руб., снижение 160/4000 = 4%."},{"n":44,"level":"C","text":"Упаковка краски — 2 л, расход 0,14 л на 1 м2, окрашивают 41 м2. Сколько банок понадобится?","answer":"3 банки.","solution":"41 · 0,14 = 5,74 л; 5,74/2 = 2,87, округляем вверх."},{"n":45,"level":"C","text":"Приближённое значение 48 получено с относительной погрешностью не более 0,25%. Чему равна соответствующая абсолютная погрешность?","answer":"Не более 0,12.","solution":"48 · 0,0025 = 0,12."},{"n":46,"level":"C","text":"В магазине цена 7600 руб. Скидка 10%, доставка 450 руб.; во втором магазине 7150 руб. с бесплатной доставкой. Выберите вариант.","answer":"Второй, на 140 руб. дешевле.","solution":"Первый: 7600 · 0,9 + 450 = 7290 руб.; второй: 7150 руб. Разница 140 руб."},{"n":47,"level":"C","text":"При строительстве дорожки длина 2,4 км разбита на участки по 150 м. Сколько участков и сколько метров останется?","answer":"16 участков, остаток 0 м.","solution":"2,4 км = 2400 м; 2400/150 = 16."},{"n":48,"level":"C","text":"В 600 г 12%-го раствора добавили 200 г чистой воды. Каков процент вещества в новом растворе? Проверка рассуждений и анализ типичных ошибок √ √","answer":"9%.","solution":"Вещества 600 · 0,12 = 72 г, новая масса 800 г, доля 72/800 = 9%."},{"n":49,"level":"Контроль","text":"Ученик утверждает: « 50 < 7,1, значит при округлении до десятых 50 < 7,1 тоже». Объясните ошибку.","answer":"После округления получается равенство 7,1 = 7,1.","solution":"Исходное √ сравнение верно, так как 7,12 = 50,41 > 50. Но 50 ≈ 7,071, до десятых равно 7,1; строгий знак при округлении теряется."},{"n":50,"level":"Контроль","text":"Ученик считает два последовательных снижения по 10% общей скидкой 20%. Проверьте на цене 2000 руб.","answer":"Цена 1620 руб.; общая скидка 19%.","solution":"2000 · 0,92 = 1620, экономия 380 руб. от 2000, то есть 19%."},{"n":51,"level":"Контроль","text":"Тариф: 700 руб. за 12 ГБ и 50 руб. за каждый дополнительный ГБ. Ученик при расходе 14 ГБ записал 700 + 14 · 50. Исправьте.","answer":"800 руб..","solution":"Доплачивают только за 14 − 12 = 2 ГБ: 700 + 2 · 50 = 800 руб."},{"n":52,"level":"Контроль","text":"Для 32,5 м2 с запасом 5% материал продаётся пачками по 2,1 м2. Сколько пачек и почему нельзя округлить вниз?","answer":"17 пачек.","solution":"32,5 · 1,05 = 34,125 м2; 34,125/2,1 = 16,25. Нужно 17 пачек: 16 пачек не хватит."},{"n":53,"level":"Контроль","text":"Ученик получил относительную погрешность 0,02 и записал 0,02%. Найдите ошибку.","answer":"2%.","solution":"Доля 0,02 соответствует 0,02 · 100% = 2%."},{"n":54,"level":"Контроль","text":"Среднюю скорость на равных по длине участках со скоростями 40 и 60 км/ч ученик посчитал как (40 + 60)/2. При расстоянии 120 км на каждом участке найдите правильный ответ.","answer":"48 км/ч.","solution":"Времена 120/40 = 3 ч и 120/60 = 2 ч, весь путь 240 км за 5 ч; vср = 48 км/ч."}],"strong":[{"n":1,"level":"A","text":"Найдите без десятичной аппроксимации 98/ 2. √ √","answer":"7.","solution":"98/ 2 = 49 = 7. √ √"},{"n":2,"level":"A","text":"Сравните 2 17 и 70 без калькулятора. √","answer":"2 17 < 70.","solution":"Квадраты положительных чисел: 68 < 70. √"},{"n":3,"level":"A","text":"Покажите, что 27 < 5,2, сравнив квадраты.","answer":"27 < 5,2.","solution":"5,22 = 27,04 > 27."},{"n":4,"level":"A","text":"Замените 6,995 округлением до сотых и сохраните два знака после запятой.","answer":"7,00.","solution":"Округление сотых увеличивает число до 7,00."},{"n":5,"level":"A","text":"Число 0,09749 округлите до тысячных и оцените знак ошибки «приближённое минус точное».","answer":"0,097; ошибка отрицательна.","solution":"0,097 − 0,09749 = −0,00049 < 0."},{"n":6,"level":"A","text":"Сравните абсолютные погрешности замен 2,99 → 3 и 10,09 → 10.","answer":"Первая меньше: 0,01 < 0,09.","solution":"|3 − 2,99| = 0,01, |10 − 10,09| = 0,09."},{"n":7,"level":"A","text":"Запишите 0,00000075 в стандартном виде и назовите показатель.","answer":"7,5 · 10−7; показатель −7.","solution":"0,00000075 = 7,5 · 10−7. "},{"n":8,"level":"A","text":"Какое число больше: 6,2 · 105 или 5,9 · 106 ?","answer":"5,9 · 106. ","solution":"Это 5 900 000 > 620 000."},{"n":9,"level":"A","text":"Длина 1,35 км. Запишите в сантиметрах через степень десяти.","answer":"1,35 · 105 см.","solution":"1 км = 105 см."},{"n":10,"level":"A","text":"Расход 0,125 л на квадратный метр. Сколько литров нужно на 16 м2 ?","answer":"2 л.","solution":"0,125 · 16 = 2."},{"n":11,"level":"A","text":"На 500 руб. сделали скидку 12%, а затем добавили 40 руб. доставки. Сколько платить?","answer":"480 руб..","solution":"500 · 0,88 + 40 = 480."},{"n":12,"level":"A","text":"После повышения на 25% и скидки 20% цена стала 750 руб. Какова была исходная? Основные алгоритмы и прикладные модели √","answer":"750 руб..","solution":"1,25 · 0,8 = 1: цена не изменилась."},{"n":13,"level":"B","text":"Определите, между какими соседними десятыми лежит 30, сравнив квадраты.","answer":"Между 5,4 и 5,5.","solution":"5,42 = 29,16 < 30 < 30,25 = 5,52. "},{"n":14,"level":"B","text":"Выразите 7,2 · 10−4 км в сантиметрах.","answer":"72 см.","solution":"1 км = 105 см, значит 7,2 · 10−4 · 105 = 72."},{"n":15,"level":"B","text":"Отчёт указал 150 ± 0,6 кг. Найдите относительную погрешность в процентах.","answer":"0,4%.","solution":"0,6/150 · 100% = 0,4%."},{"n":16,"level":"B","text":"Величина 40,0 округлена до единиц. Какую максимальную абсолютную ошибку даёт такое округление?","answer":"Не более 0,5.","solution":"При обычном округлении до единиц абсолютная ошибка не превышает половины единицы."},{"n":17,"level":"B","text":"В лаборатории измерено 4,80 ± 0,03 м. Назовите диапазон возможных длин.","answer":"[4,77; 4,83] м.","solution":"4,8 − 0,03 = 4,77, 4,8 + 0,03 = 4,83."},{"n":18,"level":"B","text":"От 800 руб. отняли 15%, затем подняли новую цену на 15%. Изменение относительно исходной?","answer":"Снижение на 2,25%.","solution":"0,85 · 1,15 = 0,9775, итог 782 руб., разница 18 руб."},{"n":19,"level":"B","text":"После двух последовательных скидок 20% и 10% цена стала 4320 руб. Найдите исходную.","answer":"6000 руб..","solution":"0,8 · 0,9x = 4320, x = 6000."},{"n":20,"level":"B","text":"Цена выросла с 2400 до 2700 руб. Найдите процент повышения от исходной цены.","answer":"12,5%.","solution":"(2700 − 2400)/2400 · 100% = 12,5%."},{"n":21,"level":"B","text":"Тариф А: 450 + 60q руб., Б: 610 + 40q руб. При каких целых q ≥ 0 выгоднее Б?","answer":"При q ≥ 9.","solution":"610 + 40q < 450 + 60q ⇒ 160 < 20q ⇒ q > 8."},{"n":22,"level":"B","text":"Тариф А: 650 руб. до 10 ГБ, дальше 45 руб./ГБ. Б: 760 руб. до 15 ГБ, дальше 25 руб./ГБ. Найдите стоимость при 16 ГБ.","answer":"А: 920 руб.; Б: 785 руб..","solution":"А: 650 + 6 · 45 = 920; Б: 760 + 1 · 25 = 785."},{"n":23,"level":"B","text":"Сервис берёт 900 руб. за 20 единиц и 30 руб. за каждую лишнюю. Найдите стоимость при 18 и 23 единицах.","answer":"900 и 990 руб..","solution":"До пакета доплат нет; превышение 3, значит 900 + 3 · 30 = 990."},{"n":24,"level":"B","text":"В 800 г 6%-го раствора сколько граммов вещества? После удаления 200 г воды какой процент?","answer":"48 г; 8%.","solution":"Вещества 800 · 0,06 = 48 г; новая масса 600 г; доля 48/600 = 8%."},{"n":25,"level":"B","text":"Автомобиль прошёл 100 км за 2 ч и 150 км за 3 ч. Найдите среднюю скорость.","answer":"50 км/ч.","solution":"Путь 250 км за 5 ч."},{"n":26,"level":"B","text":"Путешественник сделал 4500 шагов длиной 0,8 м и ещё 1500 шагов длиной 0,7 м. Найдите суммарный путь в км.","answer":"4,65 км.","solution":"4500 · 0,8 + 1500 · 0,7 = 4650 м."},{"n":27,"level":"B","text":"После увеличения на 8% увеличения величина стала 216. Найдите исходное значение.","answer":"200.","solution":"1,08x = 216 ⇒ x = 200."},{"n":28,"level":"B","text":"В первом магазине товар за 4400 руб., доставка 550 руб.; во втором — 5000 руб. с бесплатной доставкой. Нужна ли скидка для выгоды первого магазина? √ √","answer":"Нет, первый уже дешевле на 50 руб..","solution":"4400 + 550 = 4950 < 5000. Скидка для получения выгоды не требуется. √ √ √"},{"n":29,"level":"B","text":"Сравните 72 и 6 2.","answer":"Они равны.","solution":"72 = 36 · 2 = 6 2."},{"n":30,"level":"B","text":"Погрешность 0,012 м выражена в миллиметрах. Сколько это и чему равна доля в длине 3 м? Перенос навыка и многошаговые задачи","answer":"12 мм и 0,4%.","solution":"0,012 м = 12 мм; 0,012/3 · 100% = 0,4%."},{"n":31,"level":"C","text":"Тариф А: 560 + 35q руб., Б: 700 + 20q руб., q — целое число дополнительных единиц. Найдите наименьшее q, когда Б дешевле.","answer":"q = 10.","solution":"700 + 20q < 560 + 35q ⇒ 140 < 15q ⇒ q > 9 13. Минимальное целое q = 10."},{"n":32,"level":"C","text":"После снижения цены на 10% и затем ещё на 10% товар стоит 2025 руб. Найдите исходную цену.","answer":"2500 руб..","solution":"0,92 x = 2025 ⇒ x = 2025/0,81 = 2500."},{"n":33,"level":"C","text":"Расход материала 0,18 л/м². Для 36 м² требуется запас 8%, банки по 2 л. Сколько банок нужно?","answer":"4 банки.","solution":"36 · 0,18 · 1,08 = 6,9984 л, 6,9984/2 > 3."},{"n":34,"level":"C","text":"В первом магазине товар за 9600 руб. со скидкой 15% и доставкой 400 руб.; во втором 8500 руб. с доставкой. Где дешевле и на сколько?","answer":"Во втором, на 60 руб..","solution":"Первый: 9600 · 0,85 + 400 = 8560 руб.; второй 8500 руб. Разница 60 руб."},{"n":35,"level":"C","text":"Число a округлено до сотых как 3,14. Укажите диапазон возможных a при обычном округлении.","answer":"3,135 ≤ a < 3,145.","solution":"До двух знаков после запятой округляются значения от 3,135 включительно до 3,145 исключительно."},{"n":36,"level":"C","text":"Измерение 2,00 ± 0,01 м. Возможно ли, что истинная длина равна 2,015 м? Объясните.","answer":"Нет.","solution":"Допустимый диапазон [1,99; 2,01]; 2,015 вне диапазона."},{"n":37,"level":"C","text":"Расстояние 30 км пройдено за 30 мин, далее 45 км за 1 ч. Найдите среднюю скорость, не усредняя две скорости.","answer":"50 км/ч.","solution":"Общий путь 75 км, время 1,5 ч, скорость 75/1,5 = 50."},{"n":38,"level":"C","text":"На складе 120 плиток. После повреждения 5% их осталось сколько? Для покрытия нужно 110 целых плиток: хватит ли?","answer":"114 плиток; хватит.","solution":"Повреждено 120 · 0,05 = 6, осталось 114 ≥ 110."},{"n":39,"level":"C","text":"Сколько процентов составляет скидка, если 4800 руб. превратились в 4080 руб.? Затем найдите цену после ещё одной скидки 10%.","answer":"15%; 3672 руб..","solution":"(4800 − 4080)/4800 = 15%; 4080 · 0,9 = 3672."},{"n":40,"level":"C","text":"Абсолютная ошибка равна 0,03 кг, результат 1,5 кг. Какова относительная ошибка? Что изменится в процентах при выражении обеих масс в граммах?","answer":"2%; ничего.","solution":"0,03/1,5 = 0,02 = 2%. При смене единиц числитель и знаменатель умножатся одинаково."},{"n":41,"level":"C","text":"Приближённая длина 250 м с относительной погрешностью не более 0,6%. Запишите диапазон истинной длины.","answer":"От 248,5 до 251,5 м.","solution":"250 · 0,006 = 1,5 м; диапазон [248,5; 251,5]."},{"n":42,"level":"C","text":"Для площади 47 м2 требуется материал с запасом 12%, пачка покрывает 2,4 м2. Сколько пачек?","answer":"22 пачки.","solution":"47 · 1,12 = 52,64, 52,64/2,4 ≈ 21,93."},{"n":43,"level":"C","text":"Величина 4,8 · 10−6 км. Запишите в сантиметрах и миллиметрах.","answer":"0,48 см и 4,8 мм.","solution":"4,8 · 10−6 · 105 = 0,48 см; умножаем на 10 для мм."},{"n":44,"level":"C","text":"После роста на 30% и последующего снижения на 30% цена равна 8190 руб. Найдите первоначальную.","answer":"9000 руб..","solution":"1,3 · 0,7 = 0,91, x = 8190/0,91 = 9000."},{"n":45,"level":"C","text":"Тариф А 620 руб. за 12 ГБ и 40 руб./ГБ сверху; Б — 750 руб. за 16 ГБ и 30 руб./ГБ сверху. При использовании 15 ГБ что дешевле?","answer":"А на 10 руб..","solution":"А: 620 + 3 · 40 = 740, Б: 750; А дешевле на 10."},{"n":46,"level":"C","text":"Смартфон стоит 30 000 руб. Акция 18% и кэшбэк 5% от оплаченной суммы. Сколько составляет фактический расход после кэшбэка?","answer":"23 370 руб..","solution":"После скидки 30000 · 0,82 = 24600. Кэшбэк 24600 · 0,05 = 1230; чистый расход 23370."},{"n":47,"level":"C","text":"Одни и те же 100 км проехали сначала за 2 ч, затем следующие 100 км за 1 ч 15 мин. Вычислите среднюю скорость с точностью до десятых.","answer":"61,5 км/ч.","solution":"Время 2 + 1,25 = 3,25 ч, путь 200 км; 200/3,25 ≈ 61,538, до десятых 61,5."},{"n":48,"level":"C","text":"В 500 г 9%-го раствора долили воду, получив 3%-й раствор. Сколько граммов воды долили? Проверка рассуждений и анализ типичных ошибок","answer":"1000 г.","solution":"Масса вещества 500 · 0,09 = 45 г, общая масса 45/0,03 = 1500 г, вода 1000 г."},{"n":49,"level":"Контроль","text":"Ученик получил цену после двух скидок 30% и 20%, вычтя 50% из начальной. Приведите контрпример с ценой 1000 руб.","answer":"560 руб.; общая скидка 44%.","solution":"1000 · 0,7 · 0,8 = 560; ошибочный ответ 500."},{"n":50,"level":"Контроль","text":"Ученик сравнивает тарифы, используя для А 12 ГБ, для Б 18 ГБ. Почему вывод о выгоде необоснован?","answer":"Расход должен быть одинаковым.","solution":"Стоимость зависит от объёма потребления; сравните оба тарифа при одном и том же расходе, включая лимит и доплаты."},{"n":51,"level":"Контроль","text":"Ученик заявил: «Если две величины округляются до 4,1, значит они равны». Найдите два контрпримера.","answer":"Например, 4,06 и 4,14.","solution":"Оба числа округляются до 4,1 по правилу десятых, но 4,06 ̸= 4,14."},{"n":52,"level":"Контроль","text":"Два приближения одного числа: 7,49 и 7,5. Известно, что точное значение 7,486. Какое ближе?","answer":"7,49.","solution":"Погрешности: 0,004 и 0,014; первое приближение точнее."},{"n":53,"level":"Контроль","text":"Для 35 м2 взяли 10% запас, пачка покрывает 3 м2. Ученик купил 12 пачек. Достаточно ли?","answer":"Нет, нужно 13 пачек.","solution":"35 · 1,1 = 38,5 м2, 12 · 3 = 36 м2 мало; 13 · 3 = 39 м2. "},{"n":54,"level":"Контроль","text":"Как изменится относительная погрешность при переводе 4 ± 0,02 км в метры? Найдите её в процентах.","answer":"Не изменится: 0,5%.","solution":"0,02/4 = 0,005 = 0,5%. В метрах 20/4000 = 0,005."}]}}});})();
